import test from'node:test';import assert from'node:assert/strict';import fs from'node:fs';import{matchingPhotographs}from'../photographs.js';import{matchingRule,movementResult}from'../core.js';
const photos=JSON.parse(fs.readFileSync(new URL('../photographs.json',import.meta.url))).photographs.filter(x=>x.id.startsWith('omega-14501267-')),rules=JSON.parse(fs.readFileSync(new URL('../intelligence.json',import.meta.url))).rules;
test('vintage145.012-67 compact lookup retains suffix, representative limits and researched movement/clasp gaps',()=>{for(const ref of ['145.012-67','14501267','145 012 67']){const r=matchingRule(rules,'Omega',ref);assert.equal(r?.baseReference,'145.012-67');assert.ok(r.manualReview&&r.exactReferenceOnly);assert.equal(movementResult(r,'321').level,'match');assert.match(r.size,/40mm/);assert.match(r.production,/not established/);const p=matchingPhotographs(photos,'Omega',ref,{externalOnly:true});assert.deepEqual(p.map(x=>x.category).sort(),['caseback','front']);assert.ok(p.every(x=>x.matchScope==='representative variant'));}for(const ref of ['145.012','145.012-67 SP','145.012-68','145.022-67','105.012','Ultraman'])assert.equal(matchingPhotographs(photos,'Omega',ref).length,0);});
